package io.github.windyzhu3.ontologylaw.contract;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ContractConflictSnapshotTest {
 @Test void other_or_signer_roles_require_more_information_in_scope_or_exact_matching_corpus(){var id=UUID.randomUUID();var client=new ContractConflictSnapshot.Party(UUID.randomUUID(),id,"CLIENT","a".repeat(64));for(String role:List.of("OTHER","SIGNER")){var uncertain=new ContractConflictSnapshot.Party(UUID.randomUUID(),id,role,"b".repeat(64));assertFalse(ContractConflictSnapshot.complete(List.of(client,uncertain),false));assertFalse(ContractConflictSnapshot.complete(List.of(client),List.of(uncertain),false));assertTrue(ContractConflictSnapshot.candidates(List.of(client),List.of(uncertain)).isEmpty());}}
 @Test void only_exact_identity_across_opposing_roles_is_a_candidate(){var party=UUID.randomUUID();var scope=List.of(new ContractConflictSnapshot.Party(UUID.randomUUID(),party,"CLIENT","a".repeat(64)));var corpus=List.of(new ContractConflictSnapshot.Party(UUID.randomUUID(),party,"OPPONENT","b".repeat(64)),new ContractConflictSnapshot.Party(UUID.randomUUID(),UUID.randomUUID(),"OPPONENT","c".repeat(64)));assertEquals(1,ContractConflictSnapshot.candidates(scope,corpus).size());}
 @Test void missing_client_or_unknown_scope_never_clear(){assertFalse(ContractConflictSnapshot.complete(List.of(),false));assertFalse(ContractConflictSnapshot.complete(List.of(new ContractConflictSnapshot.Party(UUID.randomUUID(),UUID.randomUUID(),"CLIENT","a".repeat(64))),true));}
 @Test void matching_same_role_is_not_an_opposing_role_conflict(){var party=UUID.randomUUID();assertEquals(0,ContractConflictSnapshot.candidates(List.of(new ContractConflictSnapshot.Party(UUID.randomUUID(),party,"CLIENT","a".repeat(64))),List.of(new ContractConflictSnapshot.Party(UUID.randomUUID(),party,"CLIENT","b".repeat(64)))).size());}
}
